param([ValidatePattern('^[a-z0-9-]+$')][string]$Take='mission-breakables-v1777a',[string]$Candidate='candidate-npc-combat-v1214ir',[string]$MapInfo='campaign/edge_of_the_world/eotw.mapinfo',[ValidateSet('host','client')][string]$Source='host',[ValidateSet('grenade','windblast')][string]$Cause='grenade',[double]$StandX=-8.1,[double]$StandY=1.1,[double]$StandZ=18.1,[double]$Yaw=180,[double]$Pitch=8,[string[]]$Targets=@('env_wooden_plank_03_11','env_wooden_plank_03_12'))
# 1777 (#179): v1776 with a granted native grenade (the lab grenade fixture is the lab map's only).
# 1776 (#179): a grenade (or the host's Windblast) on a plank barricade on a mission map, from either role. Both lab games
# load the mission and arm the product controller (the breakable stream and the prop rest stream); the source stands in
# front of the boarded window (mission-spots-v1775a, b3-px), takes a grenade from the lab fixture and throws it (LT), or
# casts Windblast. The target planks' steps are read in both worlds before and 8 s after, with both streams' status and
# frames of both windows. Passed: every target plank the throw broke in the source world is broken in the other world too.
# The lab is relaunched and restored at the end. Helpers from Record-MissionCoverage-v1633. Generated by make_test_1777.py.
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$lab="$root/outputs/d2-coop-lab";$out=Join-Path $PSScriptRoot $Take
$inv=[Globalization.CultureInfo]::InvariantCulture
if(Test-Path $out){throw 'Unique take required'};New-Item -ItemType Directory $out|Out-Null;Copy-Item $PSCommandPath "$out/run-script.ps1"
$Targets=@($Targets|ForEach-Object {$_-split','}|Where-Object {$_})
$pids=@{}
function FrameRole($r,$name){$hwnd=(Get-Process -Id $pids[$r]).MainWindowHandle.ToInt64()
 & (Get-Command ffmpeg).Source -hide_banner -loglevel error -nostdin -f lavfi -i "gfxcapture=hwnd=${hwnd}:capture_cursor=0:max_framerate=30:width=-2:height=-2,hwdownload,format=bgra" -frames:v 1 -y "$out/$name-$r.png" 2>$null|Out-Null}
function Steps($r){$m=[ordered]@{};foreach($b in @((Q $r '--breakables').breakables)){if($b.name-in$Targets){$m[$b.name]=[ordered]@{step=$b.step;steps=$b.steps;health=$b.health}}};foreach($t in $Targets){if(!$m.Contains($t)){$m[$t]='gone'}};$m}
function Save($p,$v){$v|ConvertTo-Json -Depth 15|Set-Content -LiteralPath $p}
function C($r,$cmd){& "$lab/Send-D2Command.ps1" -Role $r -Command $cmd -WaitConsumed -ReceiptTimeoutMs 8000|Out-Null}
function I($r,$b='Neutral',$ms=100,$ly=0,$lx=0){& "$lab/Send-D2Input.ps1" -Role $r -Button $b -DurationMs $ms -LeftY $ly -LeftX $lx|Out-Null}
function S($r,$suffix=''){for($a=0;$a-lt40;$a++){try{return(Get-Content "$root/work/lab-instances/$r/coop-status.json$suffix" -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)}catch{Start-Sleep -Milliseconds 25}};throw "Status unavailable $r"}
function RawQ($r,$mode){$o=& "$lab/bin/d2_runtime_probe.exe" $pids[$r] $mode 2>&1|Out-String;[pscustomobject]@{exit=$LASTEXITCODE;text=$(if($o.Length-gt600){$o.Substring(0,600)}else{$o})}}
function Q($r,$mode,$arg=0){for($a=0;$a-lt8;$a++){$raw=if($arg){& "$lab/bin/d2_runtime_probe.exe" $pids[$r] $mode $arg}else{& "$lab/bin/d2_runtime_probe.exe" $pids[$r] $mode};if(!$LASTEXITCODE){return($raw|ConvertFrom-Json)};Start-Sleep -Milliseconds 20};throw "Native read failed $mode"}
function P($x,$y,$z,$yaw,$pitch=0){'setviewpos {0} {1} {2} {3} {4}' -f ([double]$x).ToString('F3',$inv),([double]$y).ToString('F3',$inv),([double]$z).ToString('F3',$inv),([double]$yaw).ToString('F2',$inv),([double]$pitch).ToString('F1',$inv)}
function Live($r){$s=S $r;$m=S $r '.movement.json';$x=S $r '.shadow-stream.json';$a=$s.probeRenderPosition;$b=$s.remotePosition
 $d=if($a-and$b){[Math]::Sqrt(($a[0]-$b[0])*($a[0]-$b[0])+($a[1]-$b[1])*($a[1]-$b[1])+($a[2]-$b[2])*($a[2]-$b[2]))}else{999}
 @{follow=$s.probeFollowEnabled;distance=[Math]::Round($d,3);product=(S $r '.product.json').result;bank=[bool]$m.active;stream=[bool]($x.armed-and$x.ready);ok=($s.probeActorHandle-and$s.probeFollowEnabled-and$d-lt1.0-and$m.active-and$x.armed-and$x.ready-and$s.remoteFresh)}}
function WaitLive($tag,$limit=30000){$w=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 300;$p=@{host=(Live host);client=(Live client)};$ok=$p.host.ok-and$p.client.ok}while(!$ok-and$w.ElapsedMilliseconds-lt$limit);$p.ok=$ok;$p.waitMs=$w.ElapsedMilliseconds;Save "$out/live-$tag.json" $p;$p}
function WaitGameplay($limitMs){$w=[Diagnostics.Stopwatch]::StartNew();$log=[Collections.Generic.List[object]]::new();$last=@{host=0;client=0}
 do{Start-Sleep -Milliseconds 500;$ready=$true
  foreach($r in 'host','client'){$s=S $r;$log.Add(@{ms=$w.ElapsedMilliseconds;role=$r;logic=$s.localGameLogicState;pending=$s.localPendingGameLogicState;map=$s.localMapId})
   if($s.localGameLogicState-ne1-or$s.localPendingGameLogicState){$ready=$false}
   if($s.localGameLogicState-in8,15-and$w.ElapsedMilliseconds-gt5000-and$w.ElapsedMilliseconds-$last[$r]-gt1500){I $r A 300;$last[$r]=$w.ElapsedMilliseconds}
   elseif($s.localGameLogicState-eq5-and$w.ElapsedMilliseconds-$last[$r]-gt4000){I $r X 3000;$last[$r]=$w.ElapsedMilliseconds}
   elseif($s.localGameLogicState-eq12-and$w.ElapsedMilliseconds-$last[$r]-gt1500){I $r B 200;$last[$r]=$w.ElapsedMilliseconds}}
  if($ready-and(S host).localMapId-ne(S client).localMapId){$ready=$false}
 }while(!$ready-and$w.ElapsedMilliseconds-lt$limitMs);@{ready=$ready;log=@($log)}}

$mutex=[Threading.Mutex]::new($false,'Local\D2CoopLab_NativeOperation_01a11a65');$owned=$false;$failure=$null;$notes=[ordered]@{mapInfo=$MapInfo;source=$Source;cause=$Cause;targets=$Targets}
$peer=if($Source-eq'host'){'client'}else{'host'}
try{
 try{$owned=$mutex.WaitOne(0)}catch [Threading.AbandonedMutexException]{$owned=$true};if(!$owned){throw 'Native operation active'}
 $pin=Get-Content "$root/work/movement-integration/$Candidate/identity.json" -Raw|ConvertFrom-Json;$dll=(Get-FileHash "$root/work/asset-game/dinput8.dll").Hash;if($dll-ne$pin.dll){throw "Expected $Candidate"}
 foreach($r in 'host','client'){$l=Get-Content "$root/work/lab-instances/$r/launch.json" -Raw|ConvertFrom-Json;$pids[$r]=$l.pid;if((S $r).localGameLogicState-ne1){throw "$r not in gameplay"}}
 Save "$out/identity.json" ([ordered]@{candidate=$Candidate;dll=$dll;mapInfo=$MapInfo})
 foreach($r in 'host','client'){I $r;foreach($cmd in 'coop_checkpoint_sync off','coop_usable_sync off','coop_door_sync off','coop_coin_sync off','coop_npc_stream off'){C $r $cmd}}
 C host "campaign $MapInfo low corvo";C client "campaign $MapInfo low emily"
 $g=WaitGameplay 300000;Save "$out/load-log.json" $g.log;if(!$g.ready){throw 'Both instances did not reach the same mission gameplay'}
 foreach($r in 'host','client'){I $r;C $r 'coop_movement_fixture off';C $r 'coop_product_auto on'}
 $w=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 500;$ok=(S host '.product.json').result-eq'armed'-and(S client '.product.json').result-eq'armed'}while(!$ok-and$w.ElapsedMilliseconds-lt90000)
 if(!$ok){throw 'Product controller not armed on the mission'};foreach($r in 'host','client'){C $r 'coop_player_health_hold on'}
 Start-Sleep -Seconds 3
 $before=[ordered]@{host=(Steps host);client=(Steps client)};$notes.before=$before
 foreach($t in $Targets){foreach($r in 'host','client'){if($before[$r][$t]-eq'gone'){throw "Target $t missing in the $r world before the throw"}}}
 # The observer stands beside the source, out of the blast, facing the barricade too.
 C $peer (P ($StandX+0.0) ($StandY+3.0) ($StandZ+1.7) ($Yaw-30));Start-Sleep -Milliseconds 600
 C $Source (P $StandX $StandY ($StandZ+1.7) $Yaw);Start-Sleep -Milliseconds 800
 try{& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $Source -Pitch $Pitch -Quick|Out-Null}catch{}
 if($Cause-eq'grenade'){
  # 1777: the lab grenade fixture is the lab map's only (mission-breakables-v1776a: unsupported_scope_or_item_owned); a
  # granted native grenade is equipped as in Test-GrenadeReal-v1273c.
  C $Source 'coop_grant_item grenade';$fw=[Diagnostics.Stopwatch]::StartNew()
  do{Start-Sleep -Milliseconds 100;$f=(S $Source '.observer-camera.json').itemGrant}while($f.result-notin'granted_grenade_equipped','grenade_slot_occupied','grenade_equip_timeout','grenade_read_failed','refused_not_gameplay'-and$fw.ElapsedMilliseconds-lt4000)
  $notes.grant=$f;if($f.result-ne'granted_grenade_equipped'){throw "Grenade grant not equipped ($($f.result))"};Start-Sleep -Milliseconds 800
  $held=Q $Source '--player-grenade';if(!$held.equipped-or$held.quantity-lt1){throw 'Native grenade not selected'};$notes.grenade=$held
  C $Source (P $StandX $StandY ($StandZ+1.7) $Yaw);Start-Sleep -Milliseconds 500;try{& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $Source -Pitch $Pitch -Quick|Out-Null}catch{}
  foreach($r in 'host','client'){FrameRole $r 'before'}
  & "$lab/Send-D2Input.ps1" -Role $Source -LeftTrigger 255 -DurationMs 1300|Out-Null
 }else{
  if($Source-ne'host'){throw 'Windblast is the host Corvo power'}
  C host 'coop_grant_named models/powers/windblast/windblast.inventoryitem';Start-Sleep -Milliseconds 1800
  C host (P $StandX $StandY ($StandZ+1.7) $Yaw);Start-Sleep -Milliseconds 600;try{& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role host -Pitch $Pitch -Quick|Out-Null}catch{}
  foreach($r in 'host','client'){FrameRole $r 'before'}
  & "$lab/Send-D2Input.ps1" -Role host -LeftTrigger 255 -DurationMs 400|Out-Null
 }
 Start-Sleep -Milliseconds 2500;foreach($r in 'host','client'){FrameRole $r 'blast'}
 Start-Sleep -Milliseconds 5500;foreach($r in 'host','client'){FrameRole $r 'after'}
 $after=[ordered]@{host=(Steps host);client=(Steps client)};$notes.after=$after
 foreach($r in 'host','client'){foreach($sfx in '.breakable-sync.json','.prop-rest.json'){try{Copy-Item "$root/work/lab-instances/$r/coop-status.json$sfx" "$out/$r$sfx"}catch{}}}
 $broken=@($Targets|Where-Object {$after[$Source][$_]-eq'gone'-or([int]$after[$Source][$_].step-gt[int]$before[$Source][$_].step)})
 $notes.brokenInSource=$broken
 $notes.brokenInPeer=@($broken|Where-Object {$after[$peer][$_]-eq'gone'-or([int]$after[$peer][$_].step-gt[int]$before[$peer][$_].step)})
 if(!$broken.Count){throw "The $Cause broke no target plank in the $Source world"}
 if($notes.brokenInPeer.Count-ne$broken.Count){throw "Broken in the $Source world: $($broken-join ','); in the $peer world: $($notes.brokenInPeer-join ',')"}
}catch{$failure=$_.Exception.Message;try{Save "$out/failure.json" @{message=$failure;stack=$_.ScriptStackTrace}}catch{}}
finally{
 if($owned){foreach($r in 'host','client'){try{C $r 'coop_player_health_hold off';C $r 'coop_product_auto off'}catch{}}
  $mutex.ReleaseMutex();$owned=$false
  $errors=[Collections.Generic.List[string]]::new()
  try{& "$root/work/movement-integration/Deploy-SourceClock.ps1"|Out-Null}catch{$errors.Add("restore: $($_.Exception.Message)")}
  foreach($r in 'host','client'){try{$s=Get-Content "$root/work/lab-instances/$r/coop-status.json" -Raw|ConvertFrom-Json;if($s.localGameLogicState-ne1-or!$s.remoteFresh){$errors.Add("$r not restored")}}catch{$errors.Add("$r status")}}
  Save "$out/restoration.json" @{passed=(!$errors.Count);errors=@($errors)};if($errors.Count-and!$failure){$failure=$errors-join '; '}}
 Save "$out/result.json" ([ordered]@{passed=(!$failure);failure=$failure;notes=$notes;scope="1776 (#179): a $Cause on a plank barricade on a mission map from the $Source; the planks must break in both worlds"})
 $mutex.Dispose()}
if($failure){throw $failure};"PASS planks broken in both worlds: $($notes.brokenInPeer-join ',')"
